def test(name, p, q):
    print(name)
    bad, contra, conv = 0, 0, 0
    first = 0
    for n in range(1, 61):
        if p(n) and not q(n):
            bad = bad + 1
            if first == 0:
                first = n
        contra = contra + ((not q(n)) and p(n))
        conv = conv + (q(n) and not p(n))
    print(f"  statement fails {bad} times, contrapositive {contra} times")
    if first > 0:
        print(f"  first counterexample: n = {first}")
    print(f"  the converse fails {conv} times")


def even(n):
    return n % 2 == 0


def square_even(n):
    return n * n % 2 == 0


def square_by_3(n):
    return n * n % 3 == 0


def by_3(n):
    return n % 3 == 0


def square_by_4(n):
    return n * n % 4 == 0


def by_4(n):
    return n % 4 == 0


test("If n^2 is even, then n is even (Example 1)", square_even, even)
test("If 3 | n^2, then 3 | n (Example 3)", square_by_3, by_3)
test("If 4 | n^2, then 4 | n (Example 7)", square_by_4, by_4)
test("If 4 | n, then n is even", by_4, even)

