def smallest_factor(n):
    d = 2
    while d * d <= n:
        if n % d == 0:
            return d
        d = d + 1
    return n


def is_prime(n):
    return n >= 2 and smallest_factor(n) == n


def hunt(name, f):
    n = 0
    while is_prime(f(n)):
        n = n + 1
    value = f(n)
    d = smallest_factor(value)
    print(f"{name}: prime for n = 0 to {n - 1}, {n} cases")
    print(f"  counterexample n = {n}: {value} = {d} * {value // d}")


def euler(n):
    return n * n + n + 41


def fermat(n):
    return 2 ** (2 ** n) + 1


def threes(n):
    return (10 ** (n + 2) - 7) // 3


hunt("n^2 + n + 41", euler)
hunt("2^(2^n) + 1", fermat)
hunt("31, 331, 3331, ...", threes)

