def is_prime(n):
    if n < 2:
        return False
    d = 2
    while d * d <= n:
        if n % d == 0:
            return False
        d = d + 1
    return True


def smallest_factor(n):
    d = 2
    while d * d <= n:
        if n % d == 0:
            return d
        d = d + 1
    return n


n = int(input())
for i in range(n):
    a = int(input())
    b = int(input())
    k = 0
    while is_prime(k * k + a * k + b):
        k = k + 1
    value = k * k + a * k + b
    print(f"Problem {i + 1}: n^2 + ({a})n + {b} first fails at n = {k}")
    if value < 2:
        print(f"  {value} is not prime, since primes start at 2")
    else:
        d = smallest_factor(value)
        print(f"  {value} = {d} * {value // d}")
